cat > /app/kv-store.proto <<'EOF'
syntax = "proto3";

service KVStore {
  rpc GetVal (GetValRequest) returns (GetValResponse);
  rpc SetVal (SetValRequest) returns (SetValResponse);
}

message GetValRequest {
  string key = 1;
}

message GetValResponse {
  int32 val = 1;
}

message SetValRequest {
  string key = 1;
  int32 value = 2;
}

message SetValResponse {
  int32 val = 1;
}
EOF

cat > /app/server.py <<'EOF'
from concurrent import futures
import threading

import grpc

import kv_store_pb2
import kv_store_pb2_grpc


class Server(kv_store_pb2_grpc.KVStoreServicer):
    def __init__(self):
        self._store = {}
        self._lock = threading.Lock()

    def GetVal(self, request, context):
        with self._lock:
            val = self._store.get(request.key, 0)
        return kv_store_pb2.GetValResponse(val=val)

    def SetVal(self, request, context):
        with self._lock:
            self._store[request.key] = request.value
            val = self._store[request.key]
        return kv_store_pb2.SetValResponse(val=val)


def serve():
    grpc_server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), grpc_server)
    grpc_server.add_insecure_port("[::]:5328")
    grpc_server.start()
    print("KVStore server listening on port 5328")
    grpc_server.wait_for_termination()


if __name__ == "__main__":
    serve()
EOF
